param([Parameter(Mandatory=$true)][string]$LaunchFile)
$ErrorActionPreference = 'Stop'
$launch = Get-Content -Raw -LiteralPath $LaunchFile | ConvertFrom-Json
$sessionScript = Join-Path $PSScriptRoot 'visible-session.ps1'
# Both paths are generated by the bridge, not evaluated as user task text.
$arguments = '-NoLogo -NoProfile -NoExit -File "' + $sessionScript + '" -LaunchFile "' + $LaunchFile + '"'
if ($launch.terminal) {
    $arguments = '--window new --title "Codex + DeepSeek" "' + $launch.powershell + '" ' + $arguments
    $windowProcess = Start-Process -FilePath $launch.terminal -ArgumentList $arguments -WorkingDirectory $launch.cwd -WindowStyle Normal -PassThru
} else {
    $windowProcess = Start-Process -FilePath $launch.powershell -ArgumentList $arguments -WorkingDirectory $launch.cwd -WindowStyle Normal -PassThru
}
@{ window_pid = $windowProcess.Id } | ConvertTo-Json -Compress
